#!/usr/bin/env python3
"""Regenerates the generated parts of perms/PROOF.bend, in place.

  python3 gen/proof.py           rewrite the regions between the lines
                                 "# BEGIN GENERATED by gen/proof.py: <name>"
                                 and "# END GENERATED: <name>"
  python3 gen/proof.py --check   only check that they are up to date

Three regions: "covers_all", the eight cases of rwx.covers_all; "lemmas",
the per-bit induction lemma behind the umask law (see wordgen.py: it matches
every combination of the bits involved at one position); and "exec", the
proof of exec_needs_an_exec_bit, which splits the override privilege and the
three execute bits (one case survives, the others contradict the hypothesis).
Everything outside the regions is written by hand.
"""
import itertools, os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import wordgen as G

T, F = "True{}", "False{}"

def plusify(text):
    """Marks every parameter of a proof def reusable (+): proofs use them freely."""
    lines = []
    for ln in text.split("\n"):
        m = re.match(r"^def ([\w.]+)\((.*?)\) ->(.*)$", ln)
        if m and not m.group(1).startswith("Laws.") and m.group(1) not in ("bits.disc", "bits.disc2"):
            ps = [p if p.startswith(("+", "-")) or ":" not in p else "+" + p for p in m.group(2).split(", ")]
            ln = "def %s(%s) ->%s" % (m.group(1), ", ".join(ps), m.group(3))
        lines.append(ln)
    return "\n".join(lines)

def covers_all():
    out = []
    for bits in itertools.product([T, F], repeat=3):
        out.append("    case M.PermsRwx{%s}:\n      {==}\n" % ", ".join(bits))
    return "".join(out)

def lemmas():
    lem = G.lemma("bits.umask", ["k", "m", "d", "u"], [], ('eq', ('and', ('and', ('and', 'k', 'm'), ('not', ('and', 'd', 'u'))), ('not', 'm')), ('zero',)))
    return "# Per-bit lemma (generated: every combination of the bits at each position)\n\n" + lem + "\n"

def exec_law():
    out = ["def Laws.exec_needs_an_exec_bit(p, fu, fg, m, h):", "  match p m:"]
    for ovr in (T, F):
        for x2, x1, x0 in itertools.product([T, F], repeat=3):
            mp = "U32{WCon{%s, WCon{w0, WCon{r0, WCon{%s, WCon{w1, WCon{r1, WCon{%s, WCon{w2, WCon{r2, rest}}}}}}}}}}" % (x0, x1, x2)
            proc = "P.PermsProc{u, g, gs, P.PermsPrivs{%s, rs, fo}}" % ovr
            out.append("    case %s %s:" % (proc, mp))
            if (x0, x1, x2) == (F, F, F):
                out.append("      cls.noexec(U32.is_eq(u, fu), P.Perms.in_group(%s, fg), w0, r0, w1, r1, w2, r2, rest)" % proc)
            else:
                lhs = "P.Perms.access(%s, P.PermsFile{fu, fg, %s, False{}}, M.PermsRwx{False{}, False{}, True{}})" % (proc, mp)
                out.append("      bits.absurd_tf(Bool, %s, False{}, h)" % lhs)
    return "\n".join(out) + "\n\n"

REGIONS = {"covers_all": covers_all(), "lemmas": lemmas(), "exec": exec_law()}

def main():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "PROOF.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    new = src
    for name, body in REGIONS.items():
        begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = new.index(begin) + len(begin)
        j = new.index(end, i)
        new = new[:i] + plusify(body) + new[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("PROOF.bend differs from what gen/proof.py generates")
            sys.exit(1)
        print("PROOF.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)

main()
